func SetMetadata(m fyne.AppMetadata) {
	metaLock.Lock()
	defer metaLock.Unlock()
	metadata = m
}

func getMetadata() fyne.AppMetadata {
	metaLock.RLock()
	defer metaLock.RUnlock()
	return metadata
}

