package binding

import (
	"fmt"
)

// stringFromFormat creates a String binding that formats its content using the provided format string.
type stringFromFormat struct {
	base
	format string
	binds  []DataItem
}

// NewSprintf returns a String binding that formats its content using the provided format string and bindings.
// The format string should use the fmt.Sprintf formatting verbs (e.g., "%s", "%d", "%f").
// The number of verbs must match the number of bindings provided.
//
// Since: 2.2
func NewSprintf(format string, bindings ...DataItem) String {
	if len(bindings) == 0 {
		// Return a static string if no bindings provided
		str := fmt.Sprintf(format)
		return NewString().(*boundString).withValue(str)
	}

	ret := &stringFromFormat{
		format: format,
		binds:  bindings,
	}

	// Listen to all input bindings and trigger updates
	for _, bind := range bindings {
		bind.AddListener(NewDataListener(func() {
			ret.trigger()
		}))
	}

	return ret
}

// StringToStringWithFormat returns a String binding that wraps a String binding with a format.
// If the format is "%s" (identity), it returns the original binding directly without wrapping.
// Otherwise, it delegates to NewSprintf(format, str).
//
// Since: 2.2
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		// Identity format - return original binding
		return str
	}
	// Wrap with NewSprintf
	return NewSprintf(format, str)
}

func (s *stringFromFormat) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	// Collect all values from bindings
	var values []interface{}
	for _, bind := range s.binds {
		var val interface{}
		var err error

		// Type switch to get the appropriate value
		switch b := bind.(type) {
		case String:
			val, err = b.Get()
		case Int:
			val, err = b.Get()
		case Float:
			val, err = b.Get()
		case Bool:
			val, err = b.Get()
		case Untyped:
			val, err = b.Get()
		default:
			// Try to get the value via reflection or default to empty string
			val = ""
		}

		if err != nil {
			return "", err
		}
		values = append(values, val)
	}

	// Format the string
	return fmt.Sprintf(s.format, values...), nil
}

func (s *stringFromFormat) Set(string) error {
	// sprintf bindings are read-only
	return fmt.Errorf("cannot set value on a formatted string binding")
}

// Helper to set initial value
func (b *boundString) withValue(val string) String {
	*b.val = val
	return b
}

